"""First-run account creation and authenticated application settings."""
import html
import json

PAGE = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Settings · Bitcoin DCA Dashboard</title><link rel="icon" href="/favicon.ico"><link rel="apple-touch-icon" sizes="180x180" href="/apple-touch-icon.png"><style>
:root{color-scheme:dark;--bg:#0b1020;--panel:#111b2e;--line:#273650;--text:#ecf1ff;--muted:#9daec9;--accent:#8bafff}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at top left,#1d2d4b,var(--bg) 65%);color:var(--text);font:15px system-ui,sans-serif;min-height:100vh}main{max-width:1000px;margin:40px auto;padding:0 20px 40px}header{display:flex;align-items:center;gap:14px;margin-bottom:24px}header img{width:46px;height:46px}h1{font-size:26px;margin:0}h2{font-size:20px;margin:0 0 18px}h3{font-size:16px}p,.hint{color:var(--muted);line-height:1.6}.panel{background:#111a2c;border:1px solid var(--line);border-radius:12px;padding:24px;margin:20px 0}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.field{min-width:0}label{display:block;color:var(--muted);margin-bottom:7px;font-size:13px}input,select{width:100%;background:#0d1525;border:1px solid var(--line);color:var(--text);border-radius:9px;padding:12px;font:inherit}input:focus,select:focus{outline:2px solid var(--accent)}input[type=checkbox]{width:auto;margin-right:9px;accent-color:var(--accent)}.toggle{display:flex;align-items:center;color:var(--text);min-height:40px}.toggle label{margin:0;color:inherit}.hint{font-size:12px;margin-top:7px}button,.button{background:var(--accent);color:#0b1730;border:1px solid transparent;border-radius:9px;padding:11px 16px;font:600 14px system-ui;cursor:pointer;text-decoration:none;display:inline-block;transition:box-shadow .2s}button:hover,.button:hover{box-shadow:0 0 18px #8bafff65}button:disabled{opacity:.5;cursor:wait}.secondary{background:#101a2d;border-color:var(--line);color:var(--text)}.actions{display:flex;gap:12px;flex-wrap:wrap;align-items:center}.actions.end{justify-content:flex-end}#status{white-space:pre-wrap;overflow-wrap:anywhere;padding:12px 0;min-height:24px}#status.error{color:#ffacac}[hidden]{display:none!important}dialog{max-width:600px;width:calc(100% - 32px);background:var(--panel);color:var(--text);border:1px solid var(--line);border-radius:12px;padding:24px}dialog::backdrop{background:#030713b8;backdrop-filter:blur(5px)}dialog dl{display:grid;grid-template-columns:1fr 1fr;gap:10px}dialog dd{margin:0;overflow-wrap:anywhere}dialog dt{color:var(--muted)}@media(max-width:600px){.grid{grid-template-columns:1fr}main{margin-top:24px}.panel{padding:18px}h1{font-size:21px}}
.embedded{background:#121a2d;min-height:0}.embedded main{max-width:none;margin:0;padding:0 20px 20px}.embedded header{display:none}.embedded .panel{background:#10182a;margin:18px 0}.embedded #settingsForm>.actions:first-child{display:none}@media(max-width:600px){.embedded main{padding:0 14px 14px}}
</style></head><body><main><header><img src="/bitcoin-dca-icon-v3.png" alt=""><h1>Bitcoin DCA Dashboard</h1></header>
<section id="accountPanel" class="panel" hidden><h2>1. Create your account</h2><p>Create your dashboard credentials to continue with configuration.</p><form id="accountForm"><div class="grid"><div><label for="newUsername">Username</label><input id="newUsername" autocomplete="username" minlength="3" maxlength="64" required></div><div><label for="newPassword">Password</label><input id="newPassword" type="password" autocomplete="new-password" minlength="12" maxlength="1024" required></div><div><label for="confirmPassword">Confirm password</label><input id="confirmPassword" type="password" autocomplete="new-password" minlength="12" required></div></div><p class="hint">Use at least 12 characters. No default account is created.</p><button>Create account and continue</button></form></section>
<form id="settingsForm" hidden>
<div class="actions"><a href="/" class="button secondary" id="back">Back to dashboard</a><h2 id="pageHeading">Settings</h2></div>
<section class="panel"><h2>Account</h2><div class="grid"><div><label for="username">Username</label><input id="username" autocomplete="username" minlength="3" maxlength="64" required></div><div><label for="current_password">Current password (for account changes)</label><input id="current_password" type="password" autocomplete="current-password"></div><div><label for="password">New password (leave empty to keep)</label><input id="password" type="password" autocomplete="new-password" minlength="12" maxlength="1024"></div><div><label for="passwordConfirm">Confirm new password</label><input id="passwordConfirm" type="password" autocomplete="new-password"></div></div><p id="passwordRequired" class="hint" hidden>Change the initial password before completing configuration.</p></section>
<section class="panel"><h2>Exchange and connection</h2><div class="grid"><div><label for="exchange">Exchange</label><select id="exchange" data-setting><option>KRAKEN</option><option>BITVAVO</option></select></div><div><label for="quote">Purchase currency</label><select id="quote" data-setting><option>EUR</option><option>USD</option></select></div></div><p class="hint">Stored API credentials are never displayed. Leave a field empty to keep its saved value. Use Bitcoin trading and balance permissions; add withdrawal permission only when needed.</p><div id="credentials" class="grid"></div><p><button id="testConnection" type="button" class="secondary">Test connection</button></p><p class="hint">Tests balance access only. Changing the exchange, currency, credentials or trading mode is blocked while transactions are unresolved.</p></section>
<section class="panel"><h2>Purchases</h2><div class="grid" id="purchaseFields"></div><label class="toggle"><input id="live" type="checkbox" data-setting>Enable live trading</label><p class="hint">Leave disabled to simulate purchases. Live trading places real market orders using the available account balance.</p></section>
<section class="panel"><h2>Withdrawals and export</h2><div class="grid"><div><label for="withdraw_threshold">Automatic withdrawal threshold (purchase currency)</label><input id="withdraw_threshold" type="number" min="0.01" step="any" data-setting required></div><div id="krakenTarget"><label for="kraken_withdraw_key">Kraken saved Bitcoin withdrawal method</label><input id="kraken_withdraw_key" data-setting></div><div id="bitvavoTarget"><label for="withdraw_address">Bitvavo Bitcoin address</label><input id="withdraw_address" data-setting></div><div id="bitvavoNetwork"><label for="withdraw_network">Bitvavo Bitcoin network</label><input id="withdraw_network" data-setting></div></div><label class="toggle"><input id="withdrawals_enabled" type="checkbox" data-setting>Enable automatic withdrawals</label><label class="toggle"><input id="manual_withdrawal_enabled" type="checkbox" data-setting>Show and allow manual withdrawals</label><label class="toggle"><input id="parqet_enabled" type="checkbox" data-setting>Show and allow Parqet CSV export</label><p class="hint">Withdrawals require live trading and a configured Bitcoin destination. Manual withdrawals require confirmation; the automatic threshold does not apply. Notes follow the enabled features.</p></section>
<div class="actions end"><button id="save" type="submit">Review and save</button></div></form>
<p id="status" role="status" aria-live="polite"></p>
<dialog id="review"><h2>Confirm configuration</h2><dl id="reviewValues"></dl><p>Settings are saved in the container’s persistent data directory. Changes take effect without rebuilding the container.</p><div class="actions end"><button type="button" class="secondary" id="cancel">Cancel</button><button type="button" id="confirm">Save configuration</button></div></dialog>
</main><script>
const initial=__INITIAL__, $=id=>document.getElementById(id);let pending=null;
function message(text,error=false){$('status').textContent=text;$('status').classList.toggle('error',error)}
async function request(path,body){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json','X-DCA-Action':'settings'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d}
function selectedExchange(){const kraken=$('exchange').value==='KRAKEN';for(const prefix of ['kraken','bitvavo'])for(const part of ['key','secret'])$(prefix+'_api_'+part).parentElement.hidden=(prefix==='kraken')!==kraken;$('krakenTarget').hidden=!kraken;$('bitvavoTarget').hidden=kraken;$('bitvavoNetwork').hidden=kraken;$('quote').options[1].disabled=!kraken;if(!kraken)$('quote').value='EUR'}
for(const prefix of ['kraken','bitvavo'])for(const part of ['key','secret']){const key=prefix+'_api_'+part,field=document.createElement('div'),label=document.createElement('label'),input=document.createElement('input');label.htmlFor=key;label.textContent=prefix[0].toUpperCase()+prefix.slice(1)+' API '+part;input.id=key;input.type='password';input.autocomplete='off';input.dataset.setting='';input.placeholder=initial.settings[key+'_configured']?'Saved · leave empty to keep':'Not configured';field.append(label,input);$('credentials').append(field)}
const fields=[['buy_amount','BTC per purchase (0 = exchange minimum)','number','0','any'],['deposit_day','Deposit day (day of month)','number','1','1','31'],['startup_delay_seconds','Startup delay (seconds)','number','0','1','86400'],['check_interval_seconds','Account check interval (seconds)','number','60','1','86400'],['order_status_check_seconds','Open order check interval (seconds)','number','1','1','3600'],['timezone','Timezone','text']];
for(const [key,title,type,min,step,max] of fields){const field=document.createElement('div'),label=document.createElement('label'),input=document.createElement('input');label.htmlFor=key;label.textContent=title;input.id=key;input.type=type;input.required=true;input.dataset.setting='';if(min)input.min=min;if(step)input.step=step;if(max)input.max=max;field.append(label,input);$('purchaseFields').append(field)}
for(const input of document.querySelectorAll('[data-setting]')){const v=initial.settings[input.id];if(v===undefined)continue;if(input.type==='checkbox')input.checked=v;else input.value=v}
$('accountPanel').hidden=!initial.createAccount;$('settingsForm').hidden=initial.createAccount;
$('username').value=initial.username||'';if(!initial.complete){$('pageHeading').textContent='2. Configure your bot';$('back').hidden=true}
$('passwordRequired').hidden=!initial.passwordChangeRequired;if(initial.passwordChangeRequired){$('password').required=true;$('current_password').required=true}
if(initial.embedded){
 document.body.classList.add('embedded');$('back').hidden=true;$('pageHeading').hidden=true;
 document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('review').open)window.parent.postMessage({type:'dca-settings-close'},location.origin)});
}
selectedExchange();$('exchange').addEventListener('change',selectedExchange);
function values(){const result={};for(const input of document.querySelectorAll('[data-setting]')){result[input.id]=input.type==='checkbox'?input.checked:input.type==='number'&&['deposit_day','startup_delay_seconds','check_interval_seconds','order_status_check_seconds'].includes(input.id)?Number(input.value):input.value}return result}
$('accountForm').addEventListener('submit',async e=>{e.preventDefault();if($('newPassword').value!==$('confirmPassword').value){message('Passwords do not match.',true);return}const b=e.submitter;b.disabled=true;try{await request('/api/setup/account',{username:$('newUsername').value,password:$('newPassword').value});location.href='/settings'}catch(err){message(err.message,true)}finally{b.disabled=false}});
$('testConnection').addEventListener('click',async()=>{const b=$('testConnection');b.disabled=true;message('Testing connection…');try{message((await request('/api/settings/test',values())).message)}catch(err){message(err.message,true)}finally{b.disabled=false}});
$('settingsForm').addEventListener('submit',e=>{e.preventDefault();if($('password').value!==$('passwordConfirm').value){message('New passwords do not match.',true);return}pending={settings:values(),username:$('username').value,password:$('password').value,current_password:$('current_password').value};$('reviewValues').replaceChildren();const v=pending.settings;for(const [name,value] of [['Exchange',v.exchange],['Purchase currency',v.quote],['Trading mode',v.live?'LIVE — real orders':'Dry run'],['BTC per purchase',v.buy_amount==='0'?'Exchange minimum':v.buy_amount],['Automatic withdrawals',v.withdrawals_enabled?'Enabled · threshold '+v.withdraw_threshold+' '+v.quote:'Disabled'],['Withdrawal destination',v.exchange==='KRAKEN'?v.kraken_withdraw_key:v.withdraw_address+' · '+v.withdraw_network],['Manual withdrawals',v.manual_withdrawal_enabled?'Enabled':'Disabled'],['Parqet CSV',v.parqet_enabled?'Enabled':'Disabled']]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=name;dd.textContent=value||'Not configured';$('reviewValues').append(dt,dd)}$('review').showModal()});
$('cancel').addEventListener('click',()=>{$('review').close();pending=null});$('review').addEventListener('cancel',()=>{pending=null});
$('confirm').addEventListener('click',async()=>{if(!pending)return;const b=$('confirm');b.disabled=true;try{const d=await request('/api/settings',pending);pending=null;if(initial.embedded){window.parent.postMessage({type:'dca-settings-saved'},location.origin)}else{location.href='/'}}catch(err){$('review').close();message(err.message,true)}finally{b.disabled=false}});
</script></body></html>'''


def settings_page(store, create_account=False, embedded=False):
    # The unauthenticated first step must not expose imported credentials or destinations.
    data = dict(settings={}, complete=False, username='', passwordChangeRequired=False) if create_account else store.public()
    data['createAccount'] = create_account
    data['embedded'] = embedded
    encoded = json.dumps(data).replace('<', '\\u003c').replace('>', '\\u003e').replace('&', '\\u0026')
    return PAGE.replace('__INITIAL__', encoded)
